from datetime import date
from itertools import product as cartesian_product

def assemble_packages(catalog):
    req = {'origin': 'Seattle', 'destination': 'Osaka', 'depart_date': '2026-10-03', 'return_date': '2026-10-08', 'check_in': '2026-10-03', 'check_out': '2026-10-08', 'budget': 1950, 'currency': 'USD', 'min_stars': 4.0, 'activity_terms': [['market'], ['temple']]}

    def as_date(value):
        return date.fromisoformat(value[:10])

    outbound = [f for f in catalog['flight_options'] if f['origin'] == req['origin'] and f['destination'] == req['destination'] and as_date(f['departure_datetime']) == as_date(req['depart_date']) and f['currency'] == req['currency']]
    inbound = [f for f in catalog['flight_options'] if f['origin'] == req['destination'] and f['destination'] == req['origin'] and as_date(f['departure_datetime']) == as_date(req['return_date']) and f['currency'] == req['currency']]
    nights = (as_date(req['check_out']) - as_date(req['check_in'])).days
    stays = [h for h in catalog['accommodation_options'] if req['destination'].lower() in h['location'].lower() and h['check_in_date'] == req['check_in'] and h['check_out_date'] == req['check_out'] and h['star_rating'] >= req['min_stars'] and h['currency'] == req['currency']]
    activity_groups = [[a for a in catalog['activity_options'] if a['currency'] == req['currency'] and as_date(req['check_in']) <= as_date(a['activity_date']) <= as_date(req['check_out']) and any(term in a['activity_name'].lower() for term in terms)] for terms in req['activity_terms']]
    if not outbound or not inbound or not stays or any(not group for group in activity_groups):
        return []

    packages = []
    for out_flight, return_flight, stay in cartesian_product(outbound, inbound, stays):
        for activities in cartesian_product(*activity_groups):
            total = out_flight['price'] + return_flight['price'] + nights * stay['nightly_price'] + sum(a['price'] for a in activities)
            if total <= req['budget']:
                packages.append({'flight_product_codes': [out_flight['product_code'], return_flight['product_code']], 'accommodation_product_code': stay['product_code'], 'activity_product_codes': [a['product_code'] for a in activities], 'total_price': round(total, 2), 'currency': req['currency']})
    return sorted(packages, key=lambda item: item['total_price'])

